package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.OrdemProducao; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface OrdemProducaoRepository extends JpaRepository<OrdemProducao,String> { @EntityGraph(attributePaths={"produtoAcabado","cliente","materiasPrimas","materiasPrimas.produtoMateriaPrima"}) @Query("select o from OrdemProducao o where o.id=:id") Optional<OrdemProducao> detail(@Param("id")String id); @Query("select o from OrdemProducao o join fetch o.produtoAcabado order by o.numeroOrdem desc") List<OrdemProducao> listWithProduct(); boolean existsByProdutoAcabadoIdAndStatus(String produtoId,String status);  @Query("select o from OrdemProducao o join fetch o.produtoAcabado where o.status='ABERTA' order by o.numeroOrdem desc") List<OrdemProducao> abertas();
 // Quanto de cada matéria-prima as ordens ABERTAS ainda vão consumir (só sai do estoque ao finalizar).
 @Query("select i.produtoMateriaPrima.id, sum(i.quantidadeUsada) from OrdemProducaoItem i where i.ordem.status='ABERTA' group by i.produtoMateriaPrima.id") List<Object[]> comprometidoPorMateria(); }
